 if(!reference)return <section className="central-detail-section central-cost-variance"><div className="central-section-heading"><div><h3>التكلفة المقدرة مقابل الفعلية</h3><p>{batch.provisional?'تُثبت لقطة التكلفة المرجعية من متوسط المخزون عند قبول إنشاء الدفعة.':'هذه الدفعة أُنشئت قبل إضافة لقطة التكلفة المرجعية؛ التكلفة الفعلية ما زالت محفوظة بالكامل.'}</p></div><span>{batch.provisional?'في انتظار القبول':'دفعة سابقة'}</span></div></section>;
 const final=batch.status==='closed'&&!batch.provisional,actual=final?batch.outputAmount:batch.wipAmount,variance=reference.batchCost===null?null:decimal(actual).sub(reference.batchCost),variancePercent=variance&&decimal(reference.batchCost!).gt(0)?variance.div(reference.batchCost!).mul(100):null;
 const actualMaterial=decimal(batch.issuedAmount).sub(batch.returnedAmount).sub(batch.abnormalAmount),materialVariance=reference.batchCost===null?null:actualMaterial.sub(reference.batchCost);
 const receiptItems=[...new Set(batch.receipts.map(r=>r.itemId))],receiptQuantity=batch.receipts.reduce((sum,r)=>sum.add(r.quantity),decimal('0')),actualUnitCost=final&&receiptItems.length===1&&receiptQuantity.gt(0)?decimal(batch.outputAmount).div(receiptQuantity):null;
