 const [tab,setTab]=useState<Tab>('batches'),[selected,setSelected]=useState(''),[search,setSearch]=useState(''),[filter,setFilter]=useState('all'),[modal,setModal]=useState<Action|null>(null),[modalBatchId,setModalBatchId]=useState(''),[error,setError]=useState('');
